definition.script:
node("linux") {
  stage("build") {
    sh "echo pipeline ${env.BUILD_NUMBER}; mkdir -p out reports; echo pipe-${env.BUILD_NUMBER} > out/lib.txt"
    writeFile file: "reports/TEST-p.xml", text: """<testsuite name="p" tests="1"><testcase classname="p.B" name="ok" time="0.3"/></testsuite>"""
    archiveArtifacts artifacts: "out/*.txt", fingerprint: true
    stash name: "stuff", includes: "out/**"
    junit "reports/*.xml"
    withCredentials([string(credentialsId: "harness-secret", variable: "S")]) { sh "test -n \"\$S\"" }
  }
  stage("unstash") { dir("again") { unstash "stuff"; sh "cat out/lib.txt" } }
}
